INSERT INTO `produto` VALUES (1,'2025-11-10 10:19:28','LIVIA','wevneiwos',,44,444444000,'444444','1','1','99999999999',2,4,2,NULL),(2,'2025-11-10 10:47:11','fshshsh','dshsdh',,35,4363.46,'gegw','8','2','44444444444',6,3,1,NULL),(3,'2025-11-10 16:52:12','teste','teste',,123123,1231.23,'12313sd','5','2','46640998866',8,9,5,NULL),(4,'2025-11-10 13:56:35','Calça fodona','Calça fodona',,11,69.49,'CALCA','5','2','09090909090',7,7,3,NULL),(6,'2025-11-10 15:02:14','aaa','djhgjadhgkjdsahgladsbjkghlksahgkjadhgalshglashdgklsajhgklhgkahdgkjadsbglkajngladjgnlkdahnlkdahjnlçsdjhlçdshjslçfjhçljsflçhjmlçds',,325235,3253.26,'dsheshsd','3','2','44444444444',6,3,1,NULL),(13,'2025-11-11 08:19:07','jungkook fofinho viadinho','jungkook fofinho viadinho',,7,7777.77,'JKFV','1','1','55555555555',19,20,20,NULL),(14,'2025-11-14 21:30:24','Blusa Feminina Manga Longa Gola Alta Branca ','Essa Blusa Feminina é uma peça clássica e versátil, confeccionada em malha canelada na cor branca. Possui modelagem de manga longa com gola alta. Seu material garante conforto, contendo no mínimo 85% de algodão. Disponível no tamanho P.',,110,34.99,'BBGAMLP','1','1','46162797805',23,22,21,NULL),(15,'2025-11-14 21:34:59','Camisa Social Masculina Manga Longa Branca','Camisa Branca Manga Longa, tamanho G Confeccionada em tecido de primeira linha PA (60% algodão e 40% poliéster), em modelagem tradicional. Excelente caimento. Costuras reforçadas.',,50,44.9,'CSMMLBG','3','2','46162797805',23,22,21,NULL),(16,'2025-11-14 21:40:05','Camisa Estampada Masculina Manga Curta','Camisa Social Estampada Masculina Manga Curta Viscose Animal Print Unissex A Camisa Jungle é feita em viscose, tecido leve e confortável. Modelagem reta com comprimento alongado. Tamanho M.',,29,189.9,'CEMMCM','1','2','46162797805',22,22,21,NULL);
INSERT INTO `produto` VALUES (17,'2025-11-14 21:53:12','Blusa Feminina Estampada','Blusa feminina estampada com modelagem justa e manga curta. É confeccionada em malha canelada (96% Viscose, 4% Elastano) e possui gola redonda, com detalhe de picot na barra e nas mangas. Tamanho M.',,200,69.9,'BFEMCBM','3','3','46162797805',23,22,21,NULL),(18,'2025-11-14 21:57:12','Blusa básica de manga curta','Peça básica confeccionada em malha lisa com uma composição confortável de 95% algodão e 5% elastano. Tamanho PP.',,20,19.9,'BBMGVFPP','6','1','46162797805',23,22,21,NULL),(19,'2025-11-14 23:55:50','Regata linho com laços listrada','Regata em tecido com linho com listras brancas e azuis. caimento soltinho no corpo, com elástico na cintura e nas alcinhas e lacinhos no busto. Tamanho P.',,100,60.9,'RAFLP','6','2','46162797805',23,22,21,NULL),(20,'2025-11-15 17:15:40','Vestido Longo Marias Preto','O vestido preto é confeccionado em tecido leve com toque de linho sem elasticidade. A peça justa na altura do busto e da cintura e solta no comprimento possui decote frontal coração e posterior reto. Tamanho G.',,220,255.9,'VFLPG','3','1','46162797805',23,22,22,NULL),(21,'2025-11-15 17:21:10','Vestido Longo Borboleta Em Flor Preto','O vestido preto é confeccionado em tecido leve sem elasticidade. A peça solta ao corpo possui decote V, mangas curtas, detalhe frontal em nó com recorte vazado, recortes posteriores e padronagem floral em cores contrastantes. Tamanho M.',,90,190.9,'VEFLPM','6','3','46162797805',23,22,22,NULL),(22,'2025-11-15 17:25:11','Vestido Plus Size Bohêmia','Inspirado no estilo boho, ele valoriza sua silhueta com elegância e personalidade, trazendo um toque romântico e vibrante ao seu guarda-roupa. Perfeito para momentos especiais ou um passeio descontraído. Tamanho GG.',,100,190.99,'VFPSCEGG','7','1','46162797805',23,22,22,NULL);
INSERT INTO `produto` VALUES (23,'2025-11-15 17:29:40','Calça Plus Size Alfaiataria Pink','Possui cintura média, ajuste nos quadris e pernas retas, sendo versátil para diferentes ocasiões, do trabalho ao lazer. Versátil, combina com camisas, blusas ou regatas para criar looks clássicos e modernos. Tamanho GG.',,60,149.9,'CCAFSRGG','4','1','46162797805',23,22,24,NULL),(24,'2025-11-15 17:32:29','Calça Jeans Flare Hot Pant Basic','Calça flare hot pant, confeccionada em tecido jeans com elastano, trazendo mais corto à peça, bolsos frente e costas funcionais, barra tradicional, fechamento em zíper e botão. Sua lavação é jeans escuro, linhas em contraste com o tom do jeans. Tamanho M.',,133,120.99,'CJFCAM','5','2','46162797805',23,22,24,NULL),(25,'2025-11-15 17:41:35','Legging Básica Poliéster Preto','Calça Legging Preta Básica com compressão média para atividades de baixo e médio impacto. Ideal para musculação, ioga, pilates, funcional e outras atividades. Tamanho P.',,299,61.99,'CFLPP',NULL,'2','46162797805',23,22,24,NULL),(26,'2025-11-15 17:44:06','Calça Cintura Baixa Flare Feminina Jeans',' Este modelo combina o charme da cintura baixa com o elegante corte flare, criando um visual moderno e despojado. Feita com tecido jeans de alta qualidade, oferece conforto duradouro e um ajuste impecável. Tamanho M.',,189,129.99,'CFJCBM','9','3','46162797805',23,22,24,NULL),(27,'2025-11-15 17:56:38','Shampoo Baby Dove Cabelos Cacheados','O Shampoo para Cabelos Cacheados Baby Dove com óleo de coco é hipoalergênico e ajuda a manter a hidratação e os nutrientes essenciais ao couro cabeludo, mantendo os cabelos cacheados visivelmente saudáveis, macios e delicadamente perfumados. ',,100,14.9,'SICC','2','2','46162797805',27,26,34,NULL),(29,'2025-11-15 18:06:11','Shampoo, Meu Liso, Demais, Vegano','IDEAL PARA FIOS LISOS. Feito para cabelos lisos, o shampoo repara e restaura os seus fios e os mantém saudáveis por mais tempo.',,100,15.8,'SCLV','8','1','46162797805',27,26,34,NULL),(30,'2025-11-15 18:10:53','Shampoo Siàge Liso Intenso','Sua fórmula com proteína Creatina, aliada ao complexo Liss Effect, bloqueia os agentes causadores do frizz e de fios indisciplinados, deixando os cabelos hidratados, macios e com muito brilho',,20,34.5,'SCL','9','2','46162797805',27,26,34,NULL),(31,'2025-11-15 18:14:40','Condicionador Elseve Color- Cabelo Colorido','O Condicionador Elseve Color-Vive Cabelo Colorido 400ml é uma solução avançada desenvolvida pela L\'Oréal Paris para atender às necessidades específicas de cabelos coloridos ou com mechas.',,77,25.9,'CCC','4','1','46162797805',27,26,35,NULL),(32,'2025-11-15 18:16:25','Condicionador Johnson & Johnson Baby Cabelo Cacheados ','Condicionador Johnson & Johnson para cabelos cacheados infantis. Fórmula com manteiga de karité que hidrata e define os cachos, facilitando o desembaraço sem agredir a pele sensível. Livre de parabenos, sulfatos e corantes, com fragrância delicada.',,45,22.22,'CICC','4','3','46162797805',27,26,35,NULL),(33,'2025-11-15 18:20:34','Protetor Solar Nivea Sun Protect & Hidrata','Protetor solar Nivea Sun Protect & Hidrata com hidratante que oferece alta proteção ao sol. Toque seco de rápida absorção.',,200,99.15,'PSC30','7','1','46162797805',22,26,37,NULL),(34,'2025-11-15 18:24:08','Protetor Solar Facial Neutrogena Sun Fresh Derm Care','Neutrogena Sun Fresh Derm Care FPS 70 é um protetor solar desenvolvido especialmente para o rosto. Com textura leve, toque seco e sem cor, protege a pele dos raios UVA/UVB, além de contar com complexo antioxidante rejuvenescedor. ',,33,45.6,'PSF70','6','2','46162797805',22,26,37,NULL),(35,'2025-11-15 18:26:51','Protetor Solar Facial Libbs Filtrum Color','Filtrum Color FPS 70 Cor 5.0, protetor solar com cor, alta proteção UVA + UVB, toque seco e cobertura uniforme por até 12h com efeito matte e controle da oleosidade.',,57,95.6,'PSFC70','7','3','46162797805',22,26,37,NULL),(36,'2025-11-15 18:31:02','Sabonete Líquido de Glicerina Granado Verde','O Sabonete Líquido de Glicerina Verde é indicado para o corpo e mãos, tem base vegetal e 87% de ingredientes de origem natural, além da glicerina também de origem natural que auxilia na hidratação da pele',,500,26.99,'SLCV','2','1','46162797805',22,26,38,NULL),(37,'2025-11-15 18:32:36','Sabonete Líquido de Glicerina Granado Rosa','O Sabonete Líquido de Glicerina Rosa é indicado para o corpo e mãos, tem base vegetal e 87% de ingredientes de origem natural, além da glicerina também de origem natural que auxilia na hidratação da pele',,60,27.8,'SLCR','1','1','46162797805',22,26,38,NULL),(38,'2025-11-15 18:36:27','Gel de Limpeza Facial',' Gel de limpeza facial com altas concentrações de Ácido Salicílico e Glicerina. Contém 13% de um mix de tensoativos desenvolvido para remover as impurezas sem ressecar a pele, 2% de Ácido Salicílico que possui propriedades queratolíticas e anti microbiana',,140,48.99,'SFLF','3','3','46162797805',22,26,38,NULL);
INSERT INTO `produto` VALUES (39,'2025-11-15 18:42:25','Perfume Miss Dior Feminino Eau de Parfum','A fragrância brilha com notas florais frescas semelhantes a um buquê deslumbrante de inúmeras flores em incontáveis cores. François Demachy, Perfumista-Criador da Maison Dior, buscou criar uma fragrância com uma Rosa iridescente iluminada',,10,1002.6,'PIFF','5','2','46162797805',22,26,42,NULL),(40,'2025-11-15 18:47:55','Floratta Red o Boticário ','O Desodorante Colônia Floratta Red, de o Boticário, conta com acordes aromáticos deliciosos de flor da Maçã de Vermont. Ele ainda revela um aroma suave e adocicado, reunindo ainda acordes de frutas vermelhas, Flor de Laranjeira, Violeta e Flor de Lótus',,45,135.9,'PFFN','4','2','46162797805',22,26,42,NULL),(41,'2025-11-15 18:52:39','Victoria\'s Secret Bare Vanilla Body Splash','Linha corporal com notas olfativas de baunilha batida e caxemira macia',,100,143.9,'BSID','3','1','46162797805',22,26,43,NULL),(42,'2025-11-15 19:02:05','Tênis All Star Converse Cano Alto Chuck Taylor','Modelo Classico Chuk Taylor cano alto, confeccionado em material têxtil Lona super resistente, possui passadores de ilhós em metal, forro em material têxtil e palmilha em EVA. Tamanho 36.',,50,256.9,'TCAV36','6','2','46162797805',24,22,23,NULL),(43,'2025-11-15 19:07:50','Vaso Bola Ancienne','Medidas Aproximadas: C 20cm - L 20cm - A 29cm;  Peso: 1,617 Kg',,10,545.9,'VC','9','1','46162797805',25,24,30,NULL);
