INSERT INTO `produto` VALUES (48,'2025-11-24 09:56:26','xcwx','xasxas',,21008,22.22,'1sas','9','1','42955970824',33,31,46,NULL),(50,'2025-11-28 17:22:42','Sapato Masculino','O sapato da linha conforto tem  forração interna de couro, fazendo com que eles absorvam melhor o suor evitando odores.',,300,334,'SSMP','9','1','46162797805',24,22,49,NULL),(51,'2025-11-28 17:24:27','Sapato Feminino Salto Baixo Grosso','Sapato Bonequinha Lilha Shoes confeccionado em material sintético, com salto baixo e grosso. Sua palmilha possui alta absorção de impacto e umidade, com um solado emborrachado com frisos antiderrapantes para garantir maior segurança e conforto ao caminhar',,200,69.99,'SFBSP','2','3','46162797805',24,22,50,NULL),(52,'2025-11-28 17:29:46','Sapato Boneca ','Salto alto preto de bico fino ',,50,171.9,'SAPFF','3','1','46162797805',24,22,50,NULL);
INSERT INTO `produto` VALUES (53,'2025-11-28 17:33:55','Salto Alto Tiras Finas Fivela Preto','A Sandália Gabriela Salto Alto Tiras Finas Fivela Preto aposta em tiras delicadas com fivelas que destacam o cabedal com elegância e modernidade.',,100,129.99,'SAPF','10','3','46162797805',24,22,50,NULL),(54,'2025-11-28 17:36:55','Tênis Grand Court Base Suede Azul','Tênis Azul da Adidas Masculino',,90,334,'TAMCB','4','2','46162797805',24,22,23,NULL);
INSERT INTO `produto` VALUES (55,'2025-11-28 17:40:44','Tênis Couro Vermelho Cano','L.V - High Quality - Acompanha Dust bag , dust card e número de série ',,10,2599.99,'TVCBM','1','1','46162797805',24,22,23,NULL),(56,'2025-11-28 17:51:07','Bota Feminina Couro Cano Baixo','Confeccionada em couro de altíssima qualidade, possui um belo salto meia pata de 6 cm fabricado em PVC que garante um charme adicional à peça, além de proporcionar estabilidade e segurança ao caminhar. ',,40,189,'BFPCB','8','3','46162797805',24,22,51,NULL),(57,'2025-11-28 17:53:34','Bota Feminina Vittal em Couro Cano Curto','O diferencial desta bota está na facilidade do calce e usabilidade em qualquer estação. Essa característica permite que você personalize seu estilo de acordo com a ocasião.',,400,141.22,'BFCBP','7','2','46162797805',24,22,51,NULL),(59,'2025-11-30 13:10:56','uuuuuuuuuuuuuuu','kl0llll',,9997,50,'iuii','1','2','33140853890',42,37,53,NULL);
